import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const canvas=document.querySelector('#scene');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;
const scene=new THREE.Scene();scene.background=new THREE.Color(0x9bc7d0);scene.fog=new THREE.Fog(0x9bc7d0,900,6200);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,9000);
scene.add(new THREE.HemisphereLight(0xd8f2ff,0x59644b,2.1));
const sun=new THREE.DirectionalLight(0xffedc4,3.2);sun.position.set(-500,900,-700);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-500;sun.shadow.camera.right=500;sun.shadow.camera.top=500;sun.shadow.camera.bottom=-500;scene.add(sun);
const mats={grass:new THREE.MeshStandardMaterial({color:0x57784c,roughness:1}),grass2:new THREE.MeshStandardMaterial({color:0x688854,roughness:1}),asphalt:new THREE.MeshStandardMaterial({color:0x343a3b,roughness:.88}),white:new THREE.MeshStandardMaterial({color:0xf0f0dc,roughness:.34,metalness:.12}),navy:new THREE.MeshStandardMaterial({color:0x203b49,roughness:.26,metalness:.22}),glass:new THREE.MeshPhysicalMaterial({color:0x4ca3b8,roughness:.14,metalness:.1,transparent:true,opacity:.67,clearcoat:1}),rubber:new THREE.MeshStandardMaterial({color:0x171b1b,roughness:.88}),metal:new THREE.MeshStandardMaterial({color:0x919a94,metalness:.75,roughness:.3}),red:new THREE.MeshStandardMaterial({color:0xe75d43,roughness:.45})};
const groundGeo=new THREE.PlaneGeometry(8000,8000,130,130);groundGeo.rotateX(-Math.PI/2);const gp=groundGeo.attributes.position;for(let i=0;i<gp.count;i++){const x=gp.getX(i),z=gp.getZ(i),fade=Math.min(1,Math.max(0,(Math.max(Math.abs(x),Math.abs(z))-300)/900));gp.setY(i,fade*(Math.sin(x*.006+z*.003)*22+Math.sin(z*.012-x*.008)*9+Math.cos(x*.019+z*.024)*3));}groundGeo.computeVertexNormals();const ground=new THREE.Mesh(groundGeo,mats.grass);ground.receiveShadow=true;scene.add(ground);
function addBox(parent,mat,pos,scale,rot){const m=new THREE.Mesh(new THREE.BoxGeometry(...scale),mat);m.position.set(...pos);if(rot)m.rotation.set(...rot);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function addCylinder(parent,mat,pos,r1,r2,len,axis='y',segments=12){const m=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,len,segments),mat);m.position.set(...pos);if(axis==='z')m.rotation.x=Math.PI/2;if(axis==='x')m.rotation.z=Math.PI/2;m.castShadow=true;parent.add(m);return m}
function makeRunway(){const runway=addBox(scene,mats.asphalt,[0,.15,-230],[42,.3,850]);addBox(scene,mats.white,[0,.32,195],[.35,.03,48]);addBox(scene,mats.white,[0,.32,-225],[.5,.04,760]);for(let z=-570;z<80;z+=52){addBox(scene,mats.white,[0,.34,z],[.65,.035,25]);for(const x of [-15,15])addBox(scene,mats.white,[x,.34,z],[.55,.03,25]);}for(const z of [-645,185]){for(const x of [-18,18])addBox(scene,mats.white,[x,.35,z],[3,.04,10]);}for(const x of [-29,29]){addBox(scene,mats.grass2,[x,.17,-225],[.55,.08,850]);}const taxi=addBox(scene,mats.asphalt,[-85,.08,-40],[13,.16,280]);taxi.receiveShadow=true;addBox(scene,mats.asphalt,[-42,.09,99],[84,.18,12]);for(let z=150;z>-640;z-=48){const light=new THREE.Mesh(new THREE.SphereGeometry(.9,8,6),new THREE.MeshBasicMaterial({color:0xe4f3c7}));light.position.set(-22,.7,z);scene.add(light);const light2=light.clone();light2.position.x=22;scene.add(light2)}for(let i=0;i<7;i++){const x=-130-i*10,z=-70-i*78;const hangar=addBox(scene,new THREE.MeshStandardMaterial({color:i%2?0xa9b8b2:0xc2c5b5,roughness:.9}),[x,9,z],[27,18,42]);const roof=addBox(scene,new THREE.MeshStandardMaterial({color:0x485c5d,roughness:.8}),[x,19,z],[29,2,44]);roof.rotation.z=.08;}addBox(scene,new THREE.MeshStandardMaterial({color:0xd9d3ba}),[-80,1.1,80],[80,2,43]);}
makeRunway();
function makeTree(x,z,s=1){const group=new THREE.Group();group.position.set(x,0,z);const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.6*s,.9*s,5*s,7),new THREE.MeshStandardMaterial({color:0x66503a}));trunk.position.y=2.5*s;group.add(trunk);for(let i=0;i<3;i++){const crown=new THREE.Mesh(new THREE.ConeGeometry((4-i*.5)*s,(7-i)*s,7),new THREE.MeshStandardMaterial({color:i===1?0x466642:0x58774b,roughness:1}));crown.position.y=(6+i*2.7)*s;group.add(crown)}scene.add(group);}
for(let i=0;i<230;i++){let x,z;do{x=(Math.random()-.5)*1400;z=(Math.random()-.5)*1700;}while(Math.abs(x)<100&&z<240&&z>-720);makeTree(x,z,.65+Math.random()*.9)}
// A detailed, Cessna 172-inspired high-wing trainer assembled from aerodynamic surfaces.
function makePlane(){const root=new THREE.Group();const body=new THREE.Group();root.add(body);const fuselage=new THREE.Group();body.add(fuselage);
const rings=[[-5.2,.08,.08],[-4.7,.2,.2],[-3.9,.38,.38],[-2.8,.52,.52],[-1.4,.57,.56],[0,.54,.52],[1.5,.46,.45],[2.8,.34,.36],[3.6,.24,.28],[4.15,.06,.12]];const verts=[],inds=[],n=20;for(let j=0;j<rings.length;j++){let[z,ry,rx]=rings[j];for(let i=0;i<n;i++){const a=i/n*Math.PI*2;verts.push(Math.cos(a)*rx,Math.sin(a)*ry,z)}}for(let j=0;j<rings.length-1;j++)for(let i=0;i<n;i++){const a=j*n+i,b=j*n+(i+1)%n,c=(j+1)*n+(i+1)%n,d=(j+1)*n+i;inds.push(a,b,d,b,c,d)}const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));geo.setIndex(inds);geo.computeVertexNormals();const fus=new THREE.Mesh(geo,mats.white);fus.castShadow=true;fus.receiveShadow=true;fuselage.add(fus);
// high wing planform, slightly tapered with raised tips
const wingShape=new THREE.Shape();wingShape.moveTo(-.95,-.65);wingShape.lineTo(-8.1,-.38);wingShape.lineTo(-8.7,.1);wingShape.lineTo(-8.0,.38);wingShape.lineTo(-1.1,.68);wingShape.lineTo(1.1,.68);wingShape.lineTo(8,.38);wingShape.lineTo(8.7,.1);wingShape.lineTo(8.1,-.38);wingShape.lineTo(.95,-.65);wingShape.close();const wing=new THREE.Mesh(new THREE.ExtrudeGeometry(wingShape,{depth:.13,bevelEnabled:true,bevelSegments:2,steps:1,bevelSize:.045,bevelThickness:.045}),mats.white);wing.rotation.x=Math.PI/2;wing.position.y=1.45;wing.position.z=-.4;wing.castShadow=true;wing.receiveShadow=true;body.add(wing);
// dark blue wing tips and stripe
for(const s of [-1,1]){const tip=addBox(body,mats.navy,[s*7.9,1.45,-.4],[1.35,.1,.78]);tip.rotation.z=s*.018;const stripe=addBox(body,mats.navy,[s*3.25,1.48,-.4],[.56,.055,.86]);}
// stabilizer and fin
const tail=addBox(body,mats.white,[0,.15,3.55],[4.1,.13,1.08]);for(const s of [-1,1])addBox(body,mats.navy,[s*1.75,.23,3.55],[.55,.055,1.08]);const fin=new THREE.Mesh(new THREE.BoxGeometry(.14,1.65,1.35),mats.white);fin.position.set(0,.88,3.48);fin.rotation.x=-.13;fin.castShadow=true;body.add(fin);addBox(body,mats.navy,[0,1.55,3.48],[.16,.22,.52]);
// cockpit windscreen and side glazing
const windshield=new THREE.Mesh(new THREE.SphereGeometry(.54,18,12,0,Math.PI*2,0,Math.PI*.52),mats.glass);windshield.scale.set(.86,.95,1.5);windshield.position.set(0,.34,-1.45);windshield.rotation.x=Math.PI;body.add(windshield);
for(const s of [-1,1]){const window=new THREE.Mesh(new THREE.BoxGeometry(.018,.58,1.05),mats.glass);window.position.set(s*.48,.32,-.35);window.rotation.y=s*.08;body.add(window);const strut=addCylinder(body,mats.metal,[s*2.2,-.25,.25],.045,.045,2.3,'y',8);strut.rotation.z=s*.98;const gearLeg=addCylinder(body,mats.metal,[s*.72,-.68,-1],.065,.055,.82,'y');gearLeg.rotation.z=s*.35;const tire=addCylinder(body,mats.rubber,[s*.9,-1.08,-1.08],.34,.34,.18,'x',18);tire.rotation.x=Math.PI/2;}
// engine cowling, propeller, spinner and blade pair
const cowl=new THREE.Mesh(new THREE.CylinderGeometry(.39,.46,1.3,18),mats.white);cowl.rotation.x=Math.PI/2;cowl.position.set(0,-.02,-4.18);body.add(cowl);const spinner=new THREE.Mesh(new THREE.ConeGeometry(.19,.42,16),mats.metal);spinner.rotation.x=-Math.PI/2;spinner.position.set(0,0,-4.95);body.add(spinner);const prop=new THREE.Group();prop.position.set(0,0,-5);body.add(prop);for(let a=0;a<2;a++){const blade=addBox(prop,mats.navy,[0,a===0?1.15:-1.15,0],[.16,1.23,.055]);blade.rotation.z=a===0?-.2:.2;}addCylinder(prop,mats.metal,[0,0,0],.14,.14,.18,'z',12);
// red registration stripe and tail registration
const stripe=addBox(body,mats.red,[0,.37,1.35],[.88,.085,.13]);const letters=addBox(body,mats.navy,[0,.22,2.4],[.12,.08,.4]);
// instrument-like landing light
for(const s of [-1,1]){const lamp=new THREE.Mesh(new THREE.SphereGeometry(.12,8,8),new THREE.MeshBasicMaterial({color:0xffe6a8}));lamp.position.set(s*2.2,-.25,-.2);body.add(lamp)}
root.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true}});scene.add(root);return{root,body,prop};}
const airplane=makePlane();

