const airplane=makePlane();
const state={pos:new THREE.Vector3(0,1.3,155),vel:new THREE.Vector3(),pitch:0,roll:0,yaw:0,throttle:.08,brake:false,started:false,paused:false,landed:false,done:[false,false,false],propSpeed:0,camYaw:0,camPitch:0};airplane.root.position.copy(state.pos);
const keys={};const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));const lerp=(a,b,t)=>a+(b-a)*t;
const speedNode=document.querySelector('#speed-value'),altNode=document.querySelector('#alt-value'),rpmNode=document.querySelector('#rpm-value'),headingNode=document.querySelector('#heading-value'),vsNode=document.querySelector('#vs-value'),flapNode=document.querySelector('#flap-value');
const toast=document.querySelector('#toast');let toastTimer;function notify(text){toast.textContent=text;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),2500)}
function mission(index){if(state.done[index])return;state.done[index]=true;const id=['step-takeoff','step-cruise','step-land'][index];document.getElementById(id).classList.add('done');document.getElementById(id).classList.remove('active');const next=['step-takeoff','step-cruise','step-land'][index+1];if(next)document.getElementById(next).classList.add('active');const count=state.done.filter(Boolean).length;document.querySelector('#progress-label').textContent=`${count} / 3`;document.querySelector('#progress-bar').style.width=`${count/3*100}%`;const messages=['DECOLAGEM CONCLUÍDA · BOM VOO!','ALTITUDE DE CRUZEIRO · EXCELENTE!','POUSO PERFEITO · MISSÃO CUMPRIDA!'];notify(messages[index]);if(index===2){document.querySelector('#status-text').textContent='MISSÃO CONCLUÍDA';document.querySelector('#hint').classList.remove('hidden');document.querySelector('#hint b').textContent='MISSÃO CONCLUÍDA';document.querySelector('#hint small').textContent='Parabéns, comandante. Voo perfeito.'}}
function setHint(title,desc){document.querySelector('#hint b').textContent=title;document.querySelector('#hint small').textContent=desc;document.querySelector('#hint').classList.remove('hidden')}
document.querySelector('#hint-close').onclick=()=>document.querySelector('#hint').classList.add('hidden');document.querySelector('#start-btn').onclick=()=>{state.started=true;document.querySelector('#start-overlay').classList.add('gone');setHint('AUMENTE A POTÊNCIA','Segure SHIFT ou toque THR + para acelerar');setTimeout(()=>document.querySelector('#hint').classList.add('hidden'),4200)};
document.querySelector('#pause-btn').onclick=()=>{if(!state.started)return;state.paused=!state.paused;document.querySelector('#game').classList.toggle('paused',state.paused);document.querySelector('#pause-btn').textContent=state.paused?'▶':'Ⅱ'};
addEventListener('keydown',e=>{keys[e.code]=true;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();if(e.code==='Escape')document.querySelector('#pause-btn').click();});addEventListener('keyup',e=>keys[e.code]=false);
let drag=null;canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&state.started){drag={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId)}});canvas.addEventListener('pointermove',e=>{if(drag){state.camYaw-= (e.clientX-drag.x)*.003;state.camPitch=clamp(state.camPitch+(e.clientY-drag.y)*.002,-.22,.3);drag={x:e.clientX,y:e.clientY}}});canvas.addEventListener('pointerup',()=>drag=null);
for(const btn of document.querySelectorAll('[data-control]')){const name=btn.dataset.control;const down=e=>{e.preventDefault();keys['Touch'+name]=true};const up=e=>{e.preventDefault();keys['Touch'+name]=false};btn.addEventListener('pointerdown',down);btn.addEventListener('pointerup',up);btn.addEventListener('pointerleave',up);btn.addEventListener('pointercancel',up)}
function button(name){return !!keys[name]}
function updateFlight(dt){if(!state.started||state.paused)return;
// Elevator and ailerons have finite response; turn rate grows with airspeed and bank.
const pitchInput=(button('KeyW')||button('ArrowUp')||button('Touchup')?1:0)-(button('KeyS')||button('ArrowDown')||button('Touchdown')?1:0);
const rollInput=(button('KeyA')||button('ArrowLeft')||button('Touchleft')?1:0)-(button('KeyD')||button('ArrowRight')||button('Touchright')?1:0);
const yawInput=(button('KeyQ')?1:0)-(button('KeyE')?1:0);
const throttleInput=(button('ShiftLeft')||button('ShiftRight')||button('Touchpower')?1:0)-(button('ControlLeft')||button('Touchbrake')?1:0);
state.throttle=clamp(state.throttle+throttleInput*dt*.2,0,1);state.brake=button('Space')||button('Touchbrake');
state.pitch=clamp(state.pitch+pitchInput*dt*.52,-.48,.46);state.roll=clamp(state.roll+rollInput*dt*.72,-.82,.82);if(!rollInput)state.roll*=Math.exp(-dt*.4);state.yaw+=yawInput*dt*.42;
const horizontal=Math.hypot(state.vel.x,state.vel.z),speed=state.vel.length(),forward=new THREE.Vector3(-Math.sin(state.yaw)*Math.cos(state.pitch),Math.sin(state.pitch),-Math.cos(state.yaw)*Math.cos(state.pitch));
if(horizontal>4)state.yaw+=Math.sin(state.roll)*Math.min(horizontal/45,1.3)*dt*.55;
const desired=new THREE.Vector3(-Math.sin(state.yaw),0,-Math.cos(state.yaw));const thrust=state.throttle*8.6;state.vel.addScaledVector(deswardFix(desired),thrust*dt);
const drag=.0065*speed*speed*(state.brake?2.9:1);if(speed>0.01)state.vel.addScaledVector(state.vel.clone().normalize(),-drag*dt);
const flightPath=Math.atan2(state.vel.y,Math.max(horizontal,1));const aoa=state.pitch-flightPath;const cl=clamp(.24+aoa*4.8,0,1.65);const lift=.0064*speed*speed*cl;state.vel.y+=(lift-9.81)*dt;
// Cessna landing gear supports weight only on the runway; brakes dissipate ground speed.
if(state.pos.y<=1.3&&state.vel.y<0&&Math.abs(state.pos.x)<26&&state.pos.z<190&&state.pos.z>-665){state.pos.y=1.3;state.vel.y=0;if(!state.landed&&speed<35&&state.done[0]){state.landed=true;mission(2)}if(state.brake){state.vel.x*=Math.exp(-dt*1.1);state.vel.z*=Math.exp(-dt*1.1)}else if(state.throttle<.12){state.vel.x*=Math.exp(-dt*.08);state.vel.z*=Math.exp(-dt*.08)}}
state.pos.addScaledVector(state.vel,dt);if(state.pos.y<1.3){state.pos.y=1.3;state.vel.y=Math.max(0,state.vel.y)}
if(!state.done[0]&&state.pos.y>4&&speed>25)mission(0);if(state.done[0]&&!state.done[1]&&state.pos.y>250)mission(1);
const hdg=(THREE.MathUtils.radToDeg(state.yaw)+360)%360,knots=speed*1.94384,feet=state.pos.y*3.28084,rpm=850+state.throttle*1850;
speedNode.textContent=String(Math.round(knots)).padStart(3,'0');altNode.textContent=String(Math.max(0,Math.round(feet))).padStart(4,'0');rpmNode.textContent=String(Math.round(rpm)).padStart(4,'0');headingNode.textContent=String(Math.round(hdg)).padStart(3,'0')+'°';vsNode.textContent=(state.vel.y>=0?'+':'')+String(Math.round(state.vel.y*196.85)).padStart(3,'0');flapNode.textContent='0°';document.querySelector('#speed-needle').style.transform=`rotate(${-122+clamp(knots/125,0,1)*244}deg)`;document.querySelector('#rpm-bar').style.width=`${(rpm-700)/2200*100}%`;document.querySelector('#alt-tape-fill').style.width=`${clamp(feet/5000,3,100)}%`;document.querySelector('#att-sky').style.transform=`rotate(${THREE.MathUtils.radToDeg(state.roll)}deg) translateY(${state.pitch*38}px)`;
if(knots>43&&state.pos.y<4){document.querySelector('#status-text').textContent='VELOCIDADE DE DECOLAGEM';}else if(state.pos.y>10){document.querySelector('#status-text').textContent=state.pos.y>250?'VOO DE CRUZEIRO':'EM VOO · SUBINDO';}else if(!state.done[0])document.querySelector('#status-text').textContent='PRONTO PARA DECOLAR';
if(state.pos.y>300&&state.done[0]&&!state.done[1])setHint('ESTABILIZE O VOO','Continue subindo até 250 m para completar a etapa');
if(state.pos.z>2300||Math.abs(state.pos.x)>2100){state.pos.set(0,1.3,155);state.vel.set(0,0,0);state.pitch=state.roll=state.yaw=0;state.throttle=.08;notify('VOO REINICIADO · VOCÊ ESTÁ DE VOLTA À PISTA')}
}
function deswardFix(v){return v}

